#include "stdlib/math/base/special/versin.h"
#include "stdlib/math/base/special/abs2.h"
#include "stdlib/math/base/special/sin.h"

/**
* Computes the versed sine.
*
* ## Method
*
* Evaluating the textbook formula
*
* ```tex
* \operatorname{versin}(x) = 1 - \cos(x)
* ```
*
* loses significant digits when `cos(x)` is close to one (i.e., for `x` near multiples of 2π, including small `x`). Accordingly, we use the equivalent half-angle identity
*
* ```tex
* \operatorname{versin}(x) = 2 \sin^2\left(\tfrac{x}{2}\right)
* ```
*
* which does not suffer from cancellation.
*
* @param x    input value (in radians)
* @return     versed sine
*
* @example
* double y = stdlib_base_versin( 0.0 );
* // returns 0.0
*/
double stdlib_base_versin( const double x ) {
	return 2.0 * stdlib_base_abs2( stdlib_base_sin( x / 2.0 ) );
}
